SELECT
    o.*,
    r.title      AS roomTitle,
    u.nick_name  AS customerName   
FROM bus_order o
LEFT JOIN bus_room r ON o.room_id = r.id
LEFT JOIN sys_user u ON o.user_id = u.user_id


    (o.user_id = #{userId} OR r.create_by = #{userId})



        AND o.status = #{bo.status}


        AND o.room_id = #{bo.roomId}


        AND o.start_date >= #{bo.startDate}


        AND o.end_date <= #{bo.endDate}



ORDER BY o.id ASC

